INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'recall', 'v.', '/rɪˈkɔːl/', '记起;回忆起;回想起', 'The smell of the soup made me recall my grandmother''s cooking.', '那汤的香味让我回想起奶奶做的饭。', 'Food', 1, 0, 'senior', 'wordlist', 'required2', 'U3', 'recall a meal', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'emerge', 'v.', '/iˈmɜːdʒ/', '暴露;被知晓;露出', 'New eating habits often emerge when people move to another country.', '人们移居他国时,新的饮食习惯常常会出现。', 'Food', 2, 0, 'senior', 'wordlist', 'required2', 'U3', 'a custom emerges', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'phase', 'n.', '/feɪz/', '阶段;时期', 'Adjusting to foreign food is just one phase of culture shock.', '适应外国食物只是文化冲击的一个阶段。', 'Food', 3, 0, 'senior', 'wordlist', 'required2', 'U3', 'a difficult phase', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'encounter', 'v.', '/ɪnˈkaʊntə(r)/', '偶然碰到;意外遇见;邂逅', 'I encountered many new dining customs during my stay in France.', '在法国期间我遇到了许多新的就餐习俗。', 'Food', 4, 0, 'senior', 'wordlist', 'required2', 'U3', 'encounter a custom', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tend', 'v.', '/tend/', '倾向;趋于;往往会', 'Many Americans tend to keep one hand in their lap while eating.', '许多美国人吃饭时往往把一只手放在大腿上。', 'Food', 5, 0, 'senior', 'wordlist', 'required2', 'U3', 'tend to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'appetite', 'n.', '/ˈæpɪtaɪt/', '食欲;胃口;强烈欲望', 'The French say "Bon appétit!" to wish you a good appetite before a meal.', '法国人在餐前说"Bon appétit!"祝你有好胃口。', 'Food', 6, 0, 'senior', 'wordlist', 'required2', 'U3', 'a good appetite', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'grab', 'v.', '/ɡræb/', '(匆忙地)取,拿,吃,喝;抓住', 'I often grab a quick coffee at a café near my host family''s home.', '我常在寄宿家庭附近的咖啡馆匆匆喝杯咖啡。', 'Food', 7, 0, 'senior', 'wordlist', 'required2', 'U3', 'grab a coffee', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'type', 'n.', '/taɪp/', '类型;种类', 'Each region of China has its own type of typical dish.', '中国每个地区都有自己典型的菜肴种类。', 'Food', 8, 0, 'senior', 'wordlist', 'required2', 'U3', 'a type of dish', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'identify', 'v.', '/aɪˈdentɪfaɪ/', '认出;确认;找到', 'We grow up eating the food of our culture and learn to identify with it.', '我们从小吃本民族的食物,并学会认同它。', 'Food', 9, 0, 'senior', 'wordlist', 'required2', 'U3', 'identify with', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'seek', 'v.', '/siːk/', '寻找;寻求', 'As adults, we often seek comfort food when we feel sad.', '成年后,我们难过时常会寻找慰藉食物。', 'Food', 10, 0, 'senior', 'wordlist', 'required2', 'U3', 'seek comfort food', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stressed', 'adj.', '/strest/', '焦虑不安的;心力交瘁的', 'Whenever I feel tired or stressed, I remember my mum''s soup.', '每当我感到疲惫或焦虑时,就会想起妈妈做的汤。', 'Food', 11, 0, 'senior', 'wordlist', 'required2', 'U3', 'feel stressed', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'identity', 'n.', '/aɪˈdentəti/', '身份;特征;特有的感觉', 'Food is an important expression of cultural identity.', '食物是文化身份的重要表达。', 'Food', 12, 0, 'senior', 'wordlist', 'required2', 'U3', 'cultural identity', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cuisine', 'n.', '/kwɪˈziːn/', '烹饪;风味;菜系', 'Chinese cuisine balances salty, spicy, sour, sweet and bitter flavours.', '中餐讲究咸、辣、酸、甜、苦五味的平衡。', 'Food', 13, 0, 'senior', 'wordlist', 'required2', 'U3', 'Chinese cuisine', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'precious', 'adj.', '/ˈpreʃəs/', '受珍爱的;珍贵的;珍稀的', 'Families pass down precious recipes from one generation to the next.', '家庭把珍贵的食谱一代代传下去。', 'Food', 14, 0, 'senior', 'wordlist', 'required2', 'U3', 'precious recipes', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'recipe', 'n.', '/ˈresəpi/', '食谱;烹饪法;秘诀', 'My grandmother''s noodle recipe has been kept for sixty years.', '我奶奶的面条食谱已经保存了六十年。', 'Food', 15, 0, 'senior', 'wordlist', 'required2', 'U3', 'a family recipe', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'means', 'n.', '/miːnz/', '方式;方法;途径', 'Cooking traditional food is a means of coping with homesickness.', '烹饪传统食物是排解思乡之情的一种方式。', 'Food', 16, 0, 'senior', 'wordlist', 'required2', 'U3', 'a means of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'unique', 'adj.', '/juˈniːk/', '独特的;独一无二的', 'Each community''s unique cuisine reflects its history and values.', '每个社群独特的饮食都反映了它的历史与价值观。', 'Food', 17, 0, 'senior', 'wordlist', 'required2', 'U3', 'a unique cuisine', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'belief', 'n.', '/bɪˈliːf/', '信念;相信;认为正确的事物', 'A nation''s food reflects its lifestyle, values and beliefs.', '一个民族的食物反映了它的生活方式、价值观和信念。', 'Food', 18, 0, 'senior', 'wordlist', 'required2', 'U3', 'values and beliefs', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'harmony', 'n.', '/ˈhɑːməni/', '融洽;和睦;和谐', 'In China, harmony is a vital trait shown in balanced dishes.', '在中国,和谐是一项重要特质,体现在味道平衡的菜肴中。', 'Food', 19, 0, 'senior', 'wordlist', 'required2', 'U3', 'in harmony', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'vital', 'adj.', '/ˈvaɪtl/', '必不可少的;极重要的', 'Balance is a vital part of cooking a good Chinese meal.', '平衡是做好一顿中餐必不可少的部分。', 'Food', 20, 0, 'senior', 'wordlist', 'required2', 'U3', 'a vital trait', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'flavour', 'n.', '/ˈfleɪvə(r)/', '味道;风味', 'Almost every flavour is used in a balanced way in Chinese dishes.', '中餐几乎将每一种味道都用得恰到好处。', 'Food', 21, 0, 'senior', 'wordlist', 'required2', 'U3', 'a rich flavour', '美式拼 flavor;美音 /ˈfleɪvər/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'spicy', 'adj.', '/ˈspaɪsi/', '加有香料的;辛辣的', 'People in Sichuan are famous for their love of spicy food.', '四川人以爱吃辣闻名。', 'Food', 22, 0, 'senior', 'wordlist', 'required2', 'U3', 'spicy food', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sour', 'adj.', '/ˈsaʊə(r)/', '酸的;有酸味的', 'Lemons have a strong sour taste that many people enjoy.', '柠檬有强烈的酸味,许多人很喜欢。', 'Food', 23, 0, 'senior', 'wordlist', 'required2', 'U3', 'a sour taste', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'bitter', 'adj.', '/ˈbɪtə(r)/', '味苦的;严寒的', 'Some green vegetables have a slightly bitter taste.', '有些绿色蔬菜带有淡淡的苦味。', 'Food', 24, 0, 'senior', 'wordlist', 'required2', 'U3', 'a bitter taste', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'style', 'n.', '/staɪl/', '风格;方式;作风', 'Chinese people have a historically elaborate cooking style.', '中国人历来有一种讲究精细的烹饪风格。', 'Food', 25, 0, 'senior', 'wordlist', 'required2', 'U3', 'a cooking style', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'costume', 'n.', '/ˈkɒstjuːm/', '服装;装束', 'A people''s careful style shows in their costumes as well as their food.', '一个民族讲究的风格既体现在服装上,也体现在食物上。', 'Food', 26, 0, 'senior', 'wordlist', 'required2', 'U3', 'traditional costumes', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'nutritious', 'adj.', '/njuˈtrɪʃəs/', '有营养的;营养丰富的', 'They believe food should be nutritious as well as appealing.', '他们认为食物既要有营养,也要诱人。', 'Food', 27, 0, 'senior', 'wordlist', 'required2', 'U3', 'nutritious food', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'appealing', 'adj.', '/əˈpiːlɪŋ/', '有吸引力的;诱人的', 'A colourful, appealing dish makes people want to start eating.', '色彩丰富、诱人的菜肴让人想立刻动筷。', 'Food', 28, 0, 'senior', 'wordlist', 'required2', 'U3', 'an appealing dish', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'access', 'v.', '/ˈækses/', '到达;进入;使用;接触', 'As the world becomes globalised, we can easily access cuisines from other cultures.', '随着世界全球化,我们能轻松接触到其他文化的菜系。', 'Food', 29, 0, 'senior', 'wordlist', 'required2', 'U3', 'access cuisines', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'inform', 'v.', '/ɪnˈfɔːm/', '了解;熟悉;通知', 'We should become more informed about other cultures by trying their dishes.', '我们应通过品尝别国菜肴,更多地了解其他文化。', 'Food', 30, 0, 'senior', 'wordlist', 'required2', 'U3', 'be informed about', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tradition', 'n.', '/trəˈdɪʃn/', '传统;惯例', 'Many French traditions focus on food and special cakes.', '许多法国传统都围绕食物和特别的蛋糕。', 'Food', 31, 0, 'senior', 'wordlist', 'required2', 'U3', 'a food tradition', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'celebrate', 'v.', '/ˈselɪbreɪt/', '庆祝;颂扬', 'We attended a dinner party to celebrate the New Year together.', '我们参加了一场晚宴一起庆祝新年。', 'Food', 32, 0, 'senior', 'wordlist', 'required2', 'U3', 'celebrate the New Year', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'course', 'n.', '/kɔːs/', '一道菜;课程;过程', 'A French dinner party often includes multiple courses.', '法国晚宴常常有好几道菜。', 'Food', 33, 0, 'senior', 'wordlist', 'required2', 'U3', 'multiple courses', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'variety', 'n.', '/vəˈraɪəti/', '多样;种类;变体', 'The meal had a variety of cheeses and slices of fresh bread.', '这顿饭有各种各样的奶酪和新鲜面包片。', 'Food', 34, 0, 'senior', 'wordlist', 'required2', 'U3', 'a variety of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'host', 'n.', '/həʊst/', '(接待客人的)主人;东道主', 'My host family welcomed me warmly to their dinner table.', '我的寄宿家庭热情地把我迎到他们的餐桌前。', 'Food', 35, 0, 'senior', 'wordlist', 'required2', 'U3', 'host family', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'custom', 'n.', '/ˈkʌstəm/', '习俗;风俗;惯例', 'Different countries observe very different dining customs.', '不同国家遵循着十分不同的就餐习俗。', 'Food', 36, 0, 'senior', 'wordlist', 'required2', 'U3', 'a dining custom', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'strategy', 'n.', '/ˈstrætədʒi/', '策略;对策', 'I learned useful strategies for dealing with culture shock.', '我学到了应对文化冲击的实用策略。', 'Food', 37, 0, 'senior', 'wordlist', 'required2', 'U3', 'learn strategies', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'illustrate', 'v.', '/ˈɪləstreɪt/', '说明;阐明;举例说明', 'She used a line graph to illustrate the highs and lows of the experience.', '她用一张折线图来说明这段经历的起起伏伏。', 'Food', 38, 0, 'senior', 'wordlist', 'required2', 'U3', 'illustrate a point', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'focus', 'v.', '/ˈfəʊkəs/', '集中(注意力);聚焦', 'Many French traditions focus on food and the family table.', '许多法国传统都聚焦于食物和家庭餐桌。', 'Food', 39, 0, 'senior', 'wordlist', 'required2', 'U3', 'focus on', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'dish', 'n.', '/dɪʃ/', '一道菜;盘;碟', 'A Chinese dinner usually starts with some cold dishes.', '中式晚餐通常以几道凉菜开始。', 'Food', 40, 0, 'senior', 'wordlist', 'required2', 'U3', 'a cold dish', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'region', 'n.', '/ˈriːdʒən/', '地区;地方;区域', 'Each region of China has its own typical New Year dishes.', '中国每个地区都有自己典型的年节菜肴。', 'Food', 41, 0, 'senior', 'wordlist', 'required2', 'U3', 'each region', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ingredient', 'n.', '/ɪnˈɡriːdiənt/', '成分;(尤指烹饪)材料', 'Immigration introduced many different ingredients to American cooking.', '移民为美国烹饪带来了许多不同的食材。', 'Food', 42, 0, 'senior', 'wordlist', 'required2', 'U3', 'fresh ingredients', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'generation', 'n.', '/ˌdʒenəˈreɪʃn/', '一代;一代人', 'Traditional cuisine is passed down from one generation to the next.', '传统菜肴一代代地传承下去。', 'Food', 43, 0, 'senior', 'wordlist', 'required2', 'U3', 'from one generation to the next', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'preserve', 'v.', '/prɪˈzɜːv/', '保存;保护;腌制', 'Immigrants cook traditional food as a way of preserving their culture.', '移民们烹饪传统食物,以此保存自己的文化。', 'Food', 44, 0, 'senior', 'wordlist', 'required2', 'U3', 'preserve culture', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'balance', 'n.', '/ˈbæləns/', '平衡;均衡', 'A good Chinese dish needs a careful balance of flavours.', '一道好的中式菜肴需要仔细的味道平衡。', 'Food', 45, 0, 'senior', 'wordlist', 'required2', 'U3', 'a balance of flavours', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'globalised', 'adj.', '/ˈɡləʊbəlaɪzd/', '全球化的', 'In a more globalised world, foreign dishes are easy to find.', '在一个更加全球化的世界里,外国菜很容易找到。', 'Food', 46, 0, 'senior', 'wordlist', 'required2', 'U3', 'a globalised world', '美式拼 globalized;美音 /ˈɡloʊbəlaɪzd/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'method', 'n.', '/ˈmeθəd/', '方法;方式', 'Boiling and steaming are two common cooking methods in China.', '煮和蒸是中国两种常见的烹饪方法。', 'Food', 47, 0, 'senior', 'wordlist', 'required2', 'U3', 'a cooking method', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'comfort', 'n.', '/ˈkʌmfət/', '安慰;慰藉;舒适', 'Family dishes often become the comfort food we seek as adults.', '家常菜常常成为我们成年后寻求的慰藉食物。', 'Food', 48, 0, 'senior', 'wordlist', 'required2', 'U3', 'comfort food', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u3.01', '①-ing 作定语(主动/正在进行)', 'A2', 10, '上外版必修第二册 U3 — 当被修饰的名词是动作的发出者、或动作正在进行时,用 -ing 形式作定语:a boiling pot(=a pot that is boiling)、the cooking method、a crying child。', 1, 'required2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u3.02', '②-ed 作定语(被动/已完成)', 'A2', 10, '上外版必修第二册 U3 — 当被修饰的名词是动作的承受者、或动作已经完成时,用 -ed 形式作定语:fried rice(=rice that has been fried)、a frozen meal、cooked food、a hidden toy。', 2, 'required2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u3.03', '③-ing vs -ed 辨析 + 复合形容词', 'A2', 10, '上外版必修第二册 U3 — 根据名词与动词的主被动关系选 -ing 还是 -ed:a man eating fish(人主动吃→-ing)vs fish eaten by a man(鱼被吃→-ed);情感类 -ing 修饰物、-ed 修饰人(a boring meal / a bored guest)。', 3, 'required2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"Be careful — that ____ pot of soup is very hot."', 'boiling', 'boiled', 'boil', 'to boil', 'A', '锅里的汤正在沸腾,主动/正在进行 → boiling。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"My grandmother taught me a simple ____ method for noodles."', 'cooked', 'cooking', 'cook', 'cooks', 'B', '表用途的方法(动名词作定语),the cooking method → cooking。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"The ____ smell of fresh bread filled the whole kitchen."', 'invited', 'invite', 'inviting', 'invites', 'C', '香味主动''诱人''→ inviting。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"A ____ child at the next table wanted some of the cake."', 'cried', 'cry', 'cries', 'crying', 'D', '孩子主动在哭,正在进行 → crying。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"We sat around the table watching the ____ steam rise from the dumplings."', 'rising', 'risen', 'rise', 'rose', 'A', '蒸汽主动上升,正在进行 → rising。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"The ____ water in the pot was ready for the noodles."', 'boiled', 'boiling', 'boil', 'boils', 'B', '水正在沸腾 → boiling water。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"There is a ____ room next to the kitchen where the family eats."', 'dined', 'dine', 'dining', 'dines', 'C', '用于吃饭的房间(动名词作定语),the dining room → dining。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"The ____ guests at the party could not wait to taste the cake."', 'waited', 'wait', 'waits', 'waiting', 'D', '客人主动在等待 → waiting guests。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"A sweet, ____ cake sat in the centre of the festive table."', 'tempting', 'tempted', 'tempt', 'tempts', 'A', '蛋糕主动''诱人''→ tempting。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"The ____ fire under the wok made the oil hiss loudly."', 'burned', 'burning', 'burn', 'burns', 'B', '火主动在燃烧,正在进行 → burning fire。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"My host mother used a special ____ board to cut the vegetables."', 'cut', 'cuts', 'cutting', 'to cut', 'C', '用于切的板(动名词作定语),a cutting board → cutting。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"The ____ aroma of the spices made everyone hungry."', 'pleased', 'please', 'pleases', 'pleasing', 'D', '香气主动令人愉悦 → pleasing。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"We watched the ____ butchers slicing meat at the busy market."', 'working', 'worked', 'work', 'works', 'A', '屠夫主动在干活,正在进行 → working butchers。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"A ____ kettle on the stove told us the tea was almost ready."', 'whistled', 'whistling', 'whistle', 'whistles', 'B', '水壶主动在''鸣响'',正在进行 → whistling kettle。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"The ____ children hid under the table before the cake was sliced."', 'laughed', 'laugh', 'laughing', 'laughs', 'C', '孩子们主动在笑 → laughing children。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"He bought a new ____ pan to fry the morning eggs."', 'fried', 'fry', 'fries', 'frying', 'D', '用来煎的锅(动名词作定语),a frying pan → frying。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"The ____ crowd at the food market grew larger by noon."', 'growing', 'grown', 'grow', 'grows', 'A', '人群主动在增多,正在进行 → growing crowd。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"A ____ pot of rice porridge bubbled gently on the stove."', 'steamed', 'steaming', 'steam', 'steams', 'B', '锅正在冒热气,正在进行 → steaming pot。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"The ____ number of food stalls made the old street very lively."', 'increased', 'increase', 'increasing', 'increases', 'C', '数量主动在增长,正在进行 → increasing number。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.01'), '"I love the ____ sound of vegetables hitting the hot oil."', 'sizzled', 'sizzle', 'sizzles', 'sizzling', 'D', '声音主动''滋滋作响'',正在进行 → sizzling sound。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"For dinner we had ____ rice with eggs and spring onions."', 'fried', 'frying', 'fry', 'fries', 'A', '米被炒过,被动/已完成 → fried rice。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"On busy nights my host family often eats a ____ meal from the freezer."', 'freezing', 'frozen', 'freeze', 'freezes', 'B', '饭被冷冻过,被动/已完成 → a frozen meal。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"Leaving some ____ food in your bowl is acceptable in China."', 'cooking', 'cook', 'cooked', 'cooks', 'C', '食物被做熟,被动/已完成 → cooked food。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"There was a small toy ____ inside the kings'' cake."', 'hiding', 'hide', 'hides', 'hidden', 'D', '玩具被藏起来,被动 → a toy hidden inside(=which is hidden)。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"In the north, ____ dumplings are a favourite New Year food."', 'boiled', 'boiling', 'boil', 'boils', 'A', '饺子被煮过,被动/已完成 → boiled dumplings。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"Near the sea, people enjoy ____ fish that is kept for the winter."', 'preserving', 'preserved', 'preserve', 'preserves', 'B', '鱼被腌制保存,被动/已完成 → preserved fish。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"The cake is best served warm, straight from the ____ oven."', 'heating', 'heat', 'heated', 'heats', 'C', '烤箱被加热,被动/已完成 → a heated oven。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"My mother placed a bowl of ____ soup beside my bed."', 'homemaking', 'homemake', 'homemakes', 'homemade', 'D', '汤是在家做成的,被动/已完成的复合形容词 → homemade soup。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"We started the meal with several ____ vegetables served cold."', 'pickled', 'pickling', 'pickle', 'pickles', 'A', '蔬菜被腌过,被动/已完成 → pickled vegetables。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"The market sold ____ meat that had been dried in the sun."', 'drying', 'dried', 'dry', 'dries', 'B', '肉被晒干,被动/已完成 → dried meat。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"A ____ crown of golden paper sat on top of the cake."', 'folding', 'fold', 'folded', 'folds', 'C', '纸冠被折成,被动/已完成 → a folded crown。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"The chef offered us some freshly ____ bread with the soup."', 'baking', 'bake', 'bakes', 'baked', 'D', '面包被烤,被动/已完成 → freshly baked bread。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"In British cooking there is a pudding ____ mostly with bread and butter."', 'made', 'making', 'make', 'makes', 'A', '布丁被做出来,被动 → a pudding made with(=which is made)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"The host put a plate of thinly ____ beef in front of me."', 'slicing', 'sliced', 'slice', 'slices', 'B', '牛肉被切片,被动/已完成 → thinly sliced beef。', 2, 14, 'mcq');
