INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"The supermarket had a whole shelf of ____ fruit in cans."', 'canning', 'can', 'cans', 'canned', 'D', '水果被装罐,被动/已完成 → canned fruit。', 2, 16, 'mcq');
