INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"The recipe used ____ ginger instead of fresh ginger root."', 'grinding', 'ground', 'grind', 'grinds', 'B', '姜被磨成粉,被动/已完成 → ground ginger。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"Each guest received a slice of cake with a ____ charm inside."', 'burying', 'bury', 'buried', 'buries', 'C', '小饰物被埋在里面,被动 → a buried charm(=which is buried)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.02'), '"On the table were small bowls of ____ rice for each member."', 'steaming', 'steam', 'steams', 'steamed', 'D', '强调''被蒸好''的米饭,被动/已完成 → steamed rice。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The waiter ____ the dishes spoke very good English."', 'serving', 'served', 'serve', 'serves', 'A', '服务员主动上菜 → the waiter serving the dishes(=who served)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The dishes ____ by the waiter looked colourful and fresh."', 'serving', 'served', 'serve', 'serves', 'B', '菜被服务员端上,被动 → the dishes served by the waiter。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The man ____ fish at the corner table was my host father."', 'eaten', 'eat', 'eating', 'eats', 'C', '人主动吃鱼 → the man eating fish(=who is eating)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The fish ____ by the man was a fresh sea sardine."', 'eating', 'eat', 'eats', 'eaten', 'D', '鱼被人吃,被动 → the fish eaten by the man。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The cook ____ the soup added a little salt and pepper."', 'making', 'made', 'make', 'makes', 'A', '厨师主动做汤 → the cook making the soup(=who made)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The soup ____ by the cook tasted rich and warm."', 'making', 'made', 'make', 'makes', 'B', '汤被厨师做,被动 → the soup made by the cook。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"It was such a ____ meal that nobody spoke for a long time."', 'satisfied', 'satisfy', 'satisfying', 'satisfies', 'C', '饭''令人满足'',-ing 修饰物 → a satisfying meal。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The ____ guests thanked the host for such a wonderful dinner."', 'satisfying', 'satisfy', 'satisfies', 'satisfied', 'D', '客人''感到满足'',-ed 修饰人 → the satisfied guests。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The students ____ Chinese food for the first time looked curious."', 'trying', 'tried', 'try', 'tries', 'A', '学生主动尝试 → the students trying Chinese food(=who were trying)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The dish ____ at the new restaurant was a regional speciality."', 'recommending', 'recommended', 'recommend', 'recommends', 'B', '菜被推荐,被动 → the dish recommended(=which was recommended)。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The woman ____ behind the stall was selling rice cakes."', 'stood', 'stand', 'standing', 'stands', 'C', '女人主动站着 → the woman standing behind(=who was standing)。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The bread ____ by my host brother was still warm."', 'buying', 'buy', 'buys', 'bought', 'D', '面包被买来,被动 → the bread bought by(=which was bought)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"After the long lunch, the ____ tourists rested in the shade."', 'tired', 'tiring', 'tire', 'tires', 'A', '游客''感到累'',-ed 修饰人 → the tired tourists。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"It had been a ____ day of visiting market after market."', 'tired', 'tiring', 'tire', 'tires', 'B', '一天''令人疲惫'',-ing 修饰物 → a tiring day。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The chef ____ the cake decorated it with a paper crown."', 'baked', 'bake', 'baking', 'bakes', 'C', '厨师主动烤蛋糕 → the chef baking the cake(=who baked)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The cake ____ in that small bakery was famous all over town."', 'baking', 'bake', 'bakes', 'baked', 'D', '蛋糕被烤,被动 → the cake baked in(=which was baked)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"Everyone found the local cooking show quite ____."', 'interesting', 'interested', 'interest', 'interests', 'A', '节目''有趣'',-ing 修饰物 → quite interesting。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The ____ visitors asked the chef many questions about the recipe."', 'interesting', 'interested', 'interest', 'interests', 'B', '客人''感兴趣'',-ed 修饰人 → the interested visitors。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The family ____ around the table shared stories about food."', 'sat', 'sit', 'sitting', 'sits', 'C', '一家人主动围坐 → the family sitting around(=who were sitting)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U3' AND code='s2u3.03'), '"The traditions ____ down for centuries still shape family meals."', 'passing', 'pass', 'passes', 'passed', 'D', '传统被世代相传,被动 → traditions passed down(=which were passed)。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Kings'' Cake', 'In the days after the New Year, the French celebrate with a special cake called the galette des rois, or the kings'' cake. It comes with its own set of fun traditions that have lasted for hundreds of years. A small toy or charm is hidden inside the cake before it is baked. Before the cake is sliced, all the children at the table hide so that they cannot see who will get each piece. Whoever finds the charm in their slice becomes king or queen for the day and wears a golden paper crown. The cake is sweet and tastes best when it is warm, straight out of the oven. People in different countries make it in many shapes and styles, but the hope is always the same: to be the lucky one who finds the little prize. For a foreign student, watching a family share this cake is a warm and surprising window into French culture.', '说明·法国国王饼传统', 158, '[{"q":"What is hidden inside the kings'' cake?","answer":"A","options":["A tiny charm or little toy.","A piece of fruit.","A golden coin.","A short letter."],"explanation":"原文 ''A small toy or charm is hidden inside the cake'' 的转述。"},{"q":"Why do the children hide before the cake is cut?","answer":"B","options":["Because they are afraid of the cake.","So they cannot see who gets each piece.","To find the kitchen.","Because the room is too hot."],"explanation":"原文 ''hide so that they cannot see who will get each piece'' 的转述。"},{"q":"What happens to the person who finds the charm?","answer":"A","options":["They get to be the day''s king or queen.","They must bake the next cake.","They leave the table.","They pay for the meal."],"explanation":"原文 ''becomes king or queen for the day'' 的转述。"}]'::jsonb, '[{"word":"celebrate","cn":"庆祝"},{"word":"tradition","cn":"传统"},{"word":"charm","cn":"小饰物"},{"word":"slice","cn":"(把……)切片;一片"}]'::jsonb, 2, 'required2', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Lesson at a Chinese Table', 'When I lived with a Chinese host family in Shanghai, my first dinner taught me a lesson about table manners. In the middle of the table were several dishes of cooked food and a small bowl of rice for each person. My host mother took charge and kept placing food into my bowl. I had been taught at home that finishing your plate shows the host how much you enjoyed the meal, so I happily ate everything. But every time my bowl was empty, she filled it again. It seemed a little odd to me, and soon I was very full. Later I learned the reason. In China, finishing your bowl is a quiet signal to the host that you would like more food. Leaving a little food behind is a polite way to show that you are satisfied. After that, I understood why my honest, hungry effort had surprised everyone. A small custom like this can cause real culture shock, but it also opens your eyes.', '记叙·中餐就餐礼仪误会', 167, '[{"q":"What did the host mother keep doing during the meal?","answer":"B","options":["Taking food away from the writer.","Refilling the writer''s bowl whenever it was empty.","Asking the writer to leave the table.","Cooking a brand-new dish."],"explanation":"原文 ''every time my bowl was empty, she filled it again'' 的转述。"},{"q":"In China, what does finishing your bowl tell the host?","answer":"C","options":["That you dislike the meal.","That you want to leave soon.","That you would welcome a second helping.","That the food is too cold."],"explanation":"原文 ''finishing your bowl is a quiet signal… you would like more food'' 的转述。"},{"q":"How is it polite to show you have had enough?","answer":"D","options":["By eating everything quickly.","By asking for a second bowl.","By standing up at once.","By leaving a little food in the bowl."],"explanation":"原文 ''Leaving a little food behind is a polite way to show that you are satisfied'' 的转述。"}]'::jsonb, '[{"word":"host","cn":"(接待客人的)主人"},{"word":"cooked","cn":"煮熟的"},{"word":"custom","cn":"习俗"},{"word":"signal","cn":"信号"}]'::jsonb, 2, 'required2', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Food and Who We Are', 'There is a deeper connection between food and culture than many people think. On an individual level, we grow up eating the food of our own culture, and we slowly learn to see it as part of who we are. Certain dishes carry special memories from childhood. When I was sick as a child, my mother used to cook soup for me, and now its smell brings back that warm feeling at once. On a larger level, food is an expression of cultural identity. Traditional cooking is passed down through families by keeping precious recipes alive. People who move to a new country often cook the food of their home as a way of staying close to their roots and dealing with homesickness. Each community''s special cuisine reflects its history, values and way of life. As the world grows more connected, it becomes easier to taste dishes from far away. We should value our own food traditions while also opening our minds to others.', '议论·食物与文化身份', 164, '[{"q":"What does the writer say food can carry on an individual level?","answer":"A","options":["Special memories from childhood.","The price of each meal.","The weather of the day.","A list of famous chefs."],"explanation":"原文 ''Certain dishes carry special memories from childhood'' 的转述。"},{"q":"Why do many people cook their home food after moving away?","answer":"B","options":["Because foreign food is not allowed.","To keep a link with home and feel less homesick.","To forget their own culture.","Because they cannot cook anything else."],"explanation":"原文 ''a way of staying close to their roots and dealing with homesickness'' 的转述。"},{"q":"What does the writer suggest we do as the world becomes more connected?","answer":"C","options":["Stop eating traditional food.","Only eat food from far away.","Value our own traditions and stay open to others.","Keep every recipe a secret."],"explanation":"末句 ''value our own food traditions while also opening our minds to others'' 的转述。"}]'::jsonb, '[{"word":"identity","cn":"身份;特征"},{"word":"recipe","cn":"食谱"},{"word":"cuisine","cn":"菜系;风味"},{"word":"roots","cn":"根源"}]'::jsonb, 2, 'required2', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Three Ways to Eat', 'Around the world, there are three main ways that people eat their food: with a knife and fork, with chopsticks, or with their fingers. Most people in Europe, Australia and North America eat with a knife and fork. Chopsticks are widely used across East Asia, in countries such as China, Japan and Korea. Eating with the fingers is actually the most widespread method of all. It is common in India, Sri Lanka, Indonesia, the Middle East and much of Africa. In fact, fewer people in the world use forks than use either chopsticks or their hands. None of these ways is better than the others; each one fits the food and the customs of its region. A traveller should never think a different method is strange or wrong. Learning to hold chopsticks, or to eat politely with your right hand, is part of understanding another culture. When you respect the way people eat, you also show respect for who they are.', '说明·世界三种进食工具', 161, '[{"q":"Which eating method is the most widespread in the world?","answer":"D","options":["Eating with a knife and fork.","Eating with chopsticks.","Eating with a spoon only.","Eating with the fingers."],"explanation":"原文 ''Eating with the fingers is actually the most widespread method of all'' 的转述。"},{"q":"Where are chopsticks said to be widely used?","answer":"A","options":["Across East Asia.","Throughout most of Africa.","In Europe and Australia.","Only in the Middle East."],"explanation":"原文 ''Chopsticks are widely used across East Asia'' 的转述。"},{"q":"What is the writer''s main point about these different methods?","answer":"B","options":["Forks are clearly the best choice.","None is better; each fits its region''s customs.","Using fingers should be avoided.","Every country should eat the same way."],"explanation":"原文 ''None of these ways is better than the others; each one fits the food and the customs of its region'' 的转述。"}]'::jsonb, '[{"word":"chopsticks","cn":"筷子"},{"word":"widespread","cn":"普遍的"},{"word":"method","cn":"方法"},{"word":"region","cn":"地区"}]'::jsonb, 2, 'required2', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Food for the New Year', 'In China, the Spring Festival is deeply connected to the country''s ancient farming culture. The dinner on New Year''s Eve is a feast of traditional foods that are believed to bring good luck for the coming year. Each region has its own typical dishes. Near the sea, families might enjoy prawns, fish salad and dried oysters. In the south, sweet rice cakes are popular, while in the north people love dumplings and steamed buns made of wheat. Many of these foods carry a hidden meaning. Long noodles, for example, stand for a long life, so you should never cut them while eating. Fish is often served because its name sounds like the word for having more than enough. A round cake can stand for a family staying together. Through these dishes, families share not only a delicious meal but also their hopes for the year ahead. Food, in this way, becomes a language of good wishes that everyone at the table understands.', '说明·中国年节食物寓意', 162, '[{"q":"Why are the New Year''s Eve foods chosen?","answer":"C","options":["They are the cheapest foods to buy.","They are easy to cook quickly.","People think they bring good fortune for the new year.","They can be kept for many months."],"explanation":"原文 ''traditional foods that are believed to bring good luck for the coming year'' 的转述。"},{"q":"Why should you not cut long noodles while eating them?","answer":"D","options":["Because they taste better whole.","Because cutting them is difficult.","Because they are too hot.","Because they are a symbol of long life."],"explanation":"原文 ''Long noodles… stand for a long life, so you should never cut them'' 的转述。"},{"q":"According to the passage, what does the food really share with the family?","answer":"A","options":["Their wishes for the months to come.","Information about farming tools.","The cost of the whole meal.","A list of southern cities."],"explanation":"原文 ''share… their hopes for the year ahead'' 的转述。"}]'::jsonb, '[{"word":"feast","cn":"盛宴"},{"word":"region","cn":"地区"},{"word":"dumpling","cn":"饺子"},{"word":"stand for","cn":"代表;象征"}]'::jsonb, 2, 'required2', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Soup I Remember', 'Some foods stay with us long after the meal is over. For me, that food is a simple bowl of chicken soup. When I was a small child and too weak to get out of bed, my mother would cook this soup and carry it to my room. I still remember the gentle steam rising from the bowl and the warm smell that filled the air. Even though I was sick, that soup made me feel safe and loved. Years later, the taste has become a part of me. Whenever I feel tired or stressed after a long day at school, I make the same soup using my mother''s recipe. The smell brings the old feeling straight back, as if she were standing beside me again. This kind of dish is often called comfort food. It does more than fill the stomach; it carries memory, family and love in every spoonful. A bowl of soup, I have learned, can be far more than just food.', '记叙·慰藉食物的记忆', 165, '[{"q":"When did the writer''s mother make the soup in the past?","answer":"B","options":["Only on New Year''s Eve.","When the writer was a sick child unable to leave bed.","Whenever guests visited.","After every school exam."],"explanation":"原文 ''too weak to get out of bed, my mother would cook this soup'' 的转述。"},{"q":"What does the writer do now when feeling tired or stressed?","answer":"C","options":["Buy soup from a shop.","Avoid eating anything.","Make the same soup from the mother''s recipe.","Call the mother to come over."],"explanation":"原文 ''I make the same soup using my mother''s recipe'' 的转述。"},{"q":"Why does the writer call the soup more than just food?","answer":"D","options":["Because it is very expensive.","Because it takes a long time to cook.","Because it is a rare dish.","Because it holds memories, warmth and family love."],"explanation":"原文 ''it carries memory, family and love in every spoonful'' 的转述。"}]'::jsonb, '[{"word":"steam","cn":"蒸汽"},{"word":"stressed","cn":"焦虑的;心力交瘁的"},{"word":"recipe","cn":"食谱"},{"word":"comfort food","cn":"慰藉食物"}]'::jsonb, 2, 'required2', 'U3', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'My First French Dinner Party', 'On my first weekend abroad, I went to a dinner party with my host family to (1)____ the New Year. It was exactly what I had imagined a French dinner would be, with many (2)____, a variety of cheeses and fresh bread. At the end of the meal, the host suddenly told everyone to get under the (3)____. I was confused until I learned about a special (4)____ called the kings'' cake. A small toy was (5)____ inside it, and the children hid so they could not see who would get the lucky (6)____. From time to time during my stay, little differences like this took me by (7)____. I felt a kind of culture (8)____, the strange feeling you get in a new country. Luckily, I had learned useful (9)____ to help me deal with these ups and downs. Looking back, I am glad I kept an open (10)____ and tried to understand.', 154, 2, '[{"q":"1","answer":"A","options":["celebrate","forget","sell","lose"],"explanation":"celebrate the New Year 庆祝新年。"},{"q":"2","answer":"B","options":["prices","courses","machines","tickets"],"explanation":"many courses 好几道菜。"},{"q":"3","answer":"C","options":["garden","river","table","shop"],"explanation":"get under the table 钻到桌子底下。"},{"q":"4","answer":"D","options":["weather","noise","price","tradition"],"explanation":"a special tradition 一项特别的传统。"},{"q":"5","answer":"A","options":["hidden","sold","thrown","eaten"],"explanation":"a toy hidden inside 被藏在里面的玩具。"},{"q":"6","answer":"B","options":["ticket","slice","song","game"],"explanation":"the lucky slice 幸运的那一块。"},{"q":"7","answer":"C","options":["bus","river","surprise","market"],"explanation":"take sb by surprise 让某人吃惊。"},{"q":"8","answer":"D","options":["price","noise","song","shock"],"explanation":"culture shock 文化冲击。"},{"q":"9","answer":"A","options":["strategies","machines","gardens","tickets"],"explanation":"useful strategies 实用的策略。"},{"q":"10","answer":"B","options":["door","mind","window","box"],"explanation":"keep an open mind 保持开放的心态。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'The Taste of India', 'Indian cooking is famous all over the world for its rich (1)____. Cooks there use lots of spices, (2)____ ginger, chilli pepper and black pepper, to give each dish a strong taste. When you walk past an Indian kitchen, the (3)____ smell of these spices fills the air at once. Many dishes are quite (4)____, so people who are not used to chillies should be careful. In much of India, people eat with their (5)____ instead of with a knife and fork. This is not a strange habit; it is simply a different (6)____ of eating that fits the local food. Each region has its own (7)____ dishes, passed down through families for many years. Some visitors find Indian food a little (8)____ at first, but most soon learn to love it. If you ever travel there, keep an open mind and (9)____ as many new dishes as you can. You may (10)____ a whole new world of flavour.', 159, 2, '[{"q":"1","answer":"C","options":["prices","machines","flavours","noises"],"explanation":"rich flavours 丰富的味道。"},{"q":"2","answer":"D","options":["selling","losing","hiding","including"],"explanation":"including ginger 包括姜。"},{"q":"3","answer":"A","options":["strong","silent","empty","cheap"],"explanation":"the strong smell 浓烈的气味。"},{"q":"4","answer":"B","options":["sweet","spicy","cold","quiet"],"explanation":"quite spicy 相当辣。"},{"q":"5","answer":"C","options":["books","wheels","fingers","wings"],"explanation":"eat with their fingers 用手吃。"},{"q":"6","answer":"D","options":["price","song","game","way"],"explanation":"a different way of eating 不同的进食方式。"},{"q":"7","answer":"A","options":["typical","empty","silent","broken"],"explanation":"its own typical dishes 自己典型的菜肴。"},{"q":"8","answer":"B","options":["cheap","strange","silent","empty"],"explanation":"a little strange 有点陌生。"},{"q":"9","answer":"C","options":["sell","drop","try","lose"],"explanation":"try as many new dishes 尽量多尝。"},{"q":"10","answer":"D","options":["forget","sell","lose","discover"],"explanation":"discover a whole new world 发现全新世界。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'A Sweet British Habit', 'The British are well known for their (1)____ for sweet food. They love biscuits, chocolates and all kinds of (2)____. One famous example is Bread and Butter Pudding, a dessert (3)____ mostly with bread and butter. It may sound (4)____ to people from other countries, but it is actually delicious. Another sweet British (5)____ is afternoon tea, when people enjoy small cakes with a hot cup of (6)____. Many of these treats are (7)____ down through families, and each home has its own slightly different (8)____. For a foreign visitor, joining a British family for tea can be a lovely way to (9)____ part of the culture. The next time someone offers you a warm slice of pudding, do not (10)____ it — you might find a new favourite.', 129, 2, '[{"q":"1","answer":"A","options":["love","fear","price","noise"],"explanation":"a love for sweet food 对甜食的喜爱。"},{"q":"2","answer":"B","options":["stones","sweets","wheels","boxes"],"explanation":"all kinds of sweets 各种糖果。"},{"q":"3","answer":"C","options":["making","make","made","makes"],"explanation":"a dessert made with 用……做的甜点(过去分词作定语)。"},{"q":"4","answer":"D","options":["cheap","empty","silent","strange"],"explanation":"sound strange 听起来奇怪。"},{"q":"5","answer":"A","options":["custom","machine","price","noise"],"explanation":"a British custom 一种英国习俗。"},{"q":"6","answer":"B","options":["oil","tea","stone","paper"],"explanation":"a cup of tea 一杯茶。"},{"q":"7","answer":"C","options":["sold","thrown","passed","lost"],"explanation":"passed down through families 代代相传。"},{"q":"8","answer":"D","options":["price","noise","ticket","recipe"],"explanation":"its own recipe 自己的食谱。"},{"q":"9","answer":"A","options":["enjoy","lose","break","sell"],"explanation":"enjoy part of the culture 体味文化的一部分。"},{"q":"10","answer":"B","options":["buy","refuse","cook","carry"],"explanation":"do not refuse it 别拒绝。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'Coffee, Italian Style', 'When I studied in Italy, I quickly learned that coffee comes with its own (1)____. In the morning, Italians enjoy a milky cappuccino, but they almost never (2)____ one after lunch. To them, a milky coffee in the afternoon seems (3)____, like having breakfast at night. If you order a cappuccino after a big meal, the waiter may give you a (4)____ look. At first this small rule (5)____ me by surprise, and I felt a little embarrassed. But my Italian friends kindly (6)____ the custom to me. They told me that, after lunch, locals usually (7)____ a small, strong espresso instead. Once I understood the (8)____ behind the habit, it made perfect sense. Now, whenever I travel, I try to learn the local food (9)____ before I order. A few minutes of asking can save you from many funny (10)____.', 141, 2, '[{"q":"1","answer":"C","options":["stones","wheels","rules","boxes"],"explanation":"its own rules 自己的规矩。"},{"q":"2","answer":"D","options":["sell","throw","lose","order"],"explanation":"never order one 从不点。"},{"q":"3","answer":"A","options":["odd","cheap","silent","empty"],"explanation":"seems odd 显得奇怪。"},{"q":"4","answer":"B","options":["surprising","surprised","surprise","surprises"],"explanation":"a surprised look 惊讶的表情(-ed 修饰表情/人的反应)。"},{"q":"5","answer":"C","options":["sold","lost","took","broke"],"explanation":"take me by surprise 让我吃惊。"},{"q":"6","answer":"D","options":["sold","lost","broke","explained"],"explanation":"explained the custom 解释这一习俗。"},{"q":"7","answer":"A","options":["drink","sell","throw","lose"],"explanation":"drink a small espresso 喝一杯浓缩咖啡。"},{"q":"8","answer":"B","options":["price","reason","noise","ticket"],"explanation":"the reason behind 背后的原因。"},{"q":"9","answer":"C","options":["prices","machines","customs","tickets"],"explanation":"local food customs 当地饮食习俗。"},{"q":"10","answer":"D","options":["songs","prices","wheels","mistakes"],"explanation":"funny mistakes 有趣的错误。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'Making Dumplings Together', 'One of my best memories of China is the night my host family taught me to make (1)____. We sat around the kitchen table while my host mother (2)____ a large bowl of meat and vegetables. She showed me how to put a little of the (3)____ into the middle of each thin wrapper and fold it closed. My first ones looked ugly, but everyone (4)____ kindly and helped me try again. Then we dropped them into a big pot of (5)____ water on the stove. While we waited, my host father (6)____ that in the north, dumplings are a favourite food for the New Year. He said their shape is (7)____ to stand for good luck and wealth. When the dumplings were finally (8)____, we ate them hot with a little vinegar. That simple meal was more (9)____ to me than any restaurant dinner. Making food together, I learned, is one of the best ways to (10)____ a new culture.', 161, 2, '[{"q":"1","answer":"A","options":["dumplings","prices","machines","tickets"],"explanation":"make dumplings 包饺子。"},{"q":"2","answer":"B","options":["sold","prepared","lost","threw"],"explanation":"prepared a bowl of 准备好一大碗。"},{"q":"3","answer":"C","options":["filled","fill","filling","fills"],"explanation":"the filling 馅料(动名词作名词)。"},{"q":"4","answer":"D","options":["sold","lost","broke","laughed"],"explanation":"everyone laughed kindly 大家善意地笑。"},{"q":"5","answer":"A","options":["boiling","boiled","boil","boils"],"explanation":"boiling water 沸水(-ing 表正在沸腾)。"},{"q":"6","answer":"B","options":["sold","explained","lost","broke"],"explanation":"explained that 解释说。"},{"q":"7","answer":"C","options":["believing","believe","believed","believes"],"explanation":"is believed to 被认为(被动)。"},{"q":"8","answer":"D","options":["empty","silent","cheap","ready"],"explanation":"were ready 做好了。"},{"q":"9","answer":"A","options":["special","empty","silent","cheap"],"explanation":"more special 更特别。"},{"q":"10","answer":"B","options":["lose","understand","sell","break"],"explanation":"understand a new culture 理解新文化。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'Food That Travels with You', 'When people move to a new country, they often bring their (1)____ food with them. Cooking a familiar dish can be a powerful way of (2)____ with homesickness. The smell of a (3)____ family recipe can make a small flat feel like home again. Over time, these dishes also become a (4)____ to the new society. Neighbours grow curious, (5)____ the new food, and slowly a community shares its (6)____. This is one reason why big cities now offer such a rich (7)____ of cuisines from around the world. As travel becomes easier and the world more (8)____, it is simpler than ever to (9)____ dishes from far-away places. We should value our own traditions, but we should also become more (10)____ about other cultures by trying their food.', 129, 2, '[{"q":"1","answer":"C","options":["empty","silent","traditional","cheap"],"explanation":"traditional food 传统食物。"},{"q":"2","answer":"D","options":["selling","losing","throwing","coping"],"explanation":"coping with homesickness 应对思乡。"},{"q":"3","answer":"A","options":["precious","empty","silent","cheap"],"explanation":"a precious family recipe 珍贵的家庭食谱。"},{"q":"4","answer":"B","options":["price","bridge","noise","wheel"],"explanation":"a bridge to the new society 通往新社会的桥梁。"},{"q":"5","answer":"C","options":["sell","lose","try","drop"],"explanation":"try the new food 尝试新食物。"},{"q":"6","answer":"D","options":["price","noise","wheel","culture"],"explanation":"shares its culture 分享其文化。"},{"q":"7","answer":"A","options":["variety","price","noise","wheel"],"explanation":"a rich variety 丰富多样。"},{"q":"8","answer":"B","options":["empty","connected","silent","cheap"],"explanation":"more connected 更紧密相连。"},{"q":"9","answer":"C","options":["lose","sell","access","break"],"explanation":"access dishes 接触到菜肴。"},{"q":"10","answer":"D","options":["empty","silent","cheap","informed"],"explanation":"more informed about 更了解。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 Ordering at a Chinese Restaurant', '上外版必修第二册 U3 · dialogue', 3, 'Waiter: Good evening. Would you like to order now?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 Dining Customs Around the World', '上外版必修第二册 U3 · passage', 2, 'Every country has its own dining customs that may surprise a visitor.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 A Question About Table Manners', '上外版必修第二册 U3 · dialogue', 3, 'Tom: I''m visiting a Chinese friend''s home tomorrow. Any advice on table manners?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 Food and Childhood Memories', '上外版必修第二册 U3 · passage', 2, 'Many of us connect our favourite foods with happy memories from childhood.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 Ordering Takeaway Food', '上外版必修第二册 U3 · dialogue', 3, 'Mia: I''m too tired to cook tonight. Shall we order some takeaway?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 Eating a Balanced Meal', '上外版必修第二册 U3 · passage', 2, 'A good meal should be both nutritious and appealing to the eye.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Giving Advice about Dining in China(给外国学生写一篇关于在中国就餐的短文)', 'Dining in China: My Advice to Foreign Students', '假设你是李华,你校学生会正在为来访的外国学生编写《在中国如何应对文化冲击》手册的《饮食与就餐习俗》栏目。请用英语写一篇约90词的短文,内容包括:① 简要介绍一项中国的食物或就餐习俗(如:共享菜肴、用筷子、不吃光碗里的饭);② 举一个可能让外国人感到文化冲击的例子;③ 做跨文化比较并简单解释原因。注意:用 -ing/-ed 作定语的表达,行文连贯。', 'Suppose you are Li Hua. Your Students'' Union is preparing a brochure to help visiting foreign students deal with culture shock in China. Write a short article (about 90 words) for the ''Foods and Dining Customs'' section, including: 1) a brief introduction to one Chinese food or dining custom (e.g. sharing dishes, using chopsticks, not finishing your bowl); 2) one example that might cause culture shock; 3) a cross-cultural comparison with a simple explanation.', '["介绍一项习俗(In China, it is common to … / One typical custom is …)","举可能造成文化冲击的例子(This may surprise visitors who …)","跨文化比较 + 解释(In many Western countries …, while in China …, because …)","用 -ing/-ed 作定语(shared dishes / steaming bowls of rice),行文连贯"]'::jsonb, 70, 100, 'In China, people usually share the dishes placed in the middle of the table, while each person has a small bowl of steamed rice. This may surprise foreign students who are used to having their own separate plate. Another custom is that you need not finish every grain in your bowl. In many Western countries, cleaning your plate shows respect, but in China leaving a little food means you are pleasantly full. Understanding these differences will help you relax and enjoy every shared, home-cooked meal with your Chinese friends.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["In China, people usually share the dishes placed in the middle of the table.","This may surprise foreign students who are used to having their own separate plate.","In many Western countries, cleaning your plate shows respect, but in China leaving a little food means you are pleasantly full.","Understanding these differences will help you enjoy every shared, home-cooked meal."]'::jsonb, '[{"wrong":"the dishes placing in the middle","correct":"the dishes placed in the middle","note":"菜被摆放,被动 → 过去分词 placed 作定语。"},{"wrong":"a bowl of steaming rice for eat","correct":"a bowl of steamed rice","note":"米被蒸熟(被动/已完成)→ steamed;强调正在冒气才用 steaming。"},{"wrong":"leaving a little food mean you are full","correct":"leaving a little food means you are full","note":"动名词短语作主语视为单数,谓语用 means。"}]'::jsonb, '【在中国就餐建议短文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required2', 'U3', '{"title":"-ing / -ed 形式作定语速查","intro":"-ing 和 -ed 形式都能放在名词前后作定语,相当于一个定语从句。判断口诀:名词是动作的发出者、或动作正在进行 → -ing(主动);名词是动作的承受者、或动作已完成 → -ed(被动/完成)。","table":{"headers":["形式","含义 / 例子 / 等价"],"rows":[["-ing(主动·进行)","boiling water = water that is boiling 正在沸腾的水"],["-ed(被动·完成)","fried rice = rice that has been fried 被炒过的饭"],["-ed(被动)","a toy hidden inside = a toy which is hidden 被藏的玩具"],["-ing(动名词作定语)","a dining room = a room for dining 用来吃饭的房间"]]},"specialRules":[{"rule":"名词主动发出动作 / 动作正在进行 → 用 -ing","mark":"a crying child(孩子主动在哭)"},{"rule":"名词被动承受动作 / 动作已完成 → 用 -ed","mark":"cooked food(食物被做熟)"},{"rule":"a man eating fish(人吃→-ing) vs fish eaten by a man(鱼被吃→-ed)","mark":"看名词与动词的主被动关系"},{"rule":"情感类:-ing 修饰物(令人……),-ed 修饰人(感到……)","mark":"a boring meal / a bored guest"}],"why":["-ing/-ed 作定语其实是一个被压缩的定语从句:water that is boiling → boiling water;rice that has been fried → fried rice。所以只要还原成从句、判断主动还是被动,就知道该用哪个形式。"],"gaokaoPoints":["语法填空高频:给出动词原形,要求填 -ing 还是 -ed,看名词与动词是主动还是被动关系。","短语作后置定语:a man carrying a suitcase / a toy hidden inside the cake,放在名词后,相当于定语从句。","情感动词分词区分(interesting/interested、boring/bored)是易错点。"],"examVsReal":[{"exam":"the dishes served by the waiter（考试/书面)","real":"the dishes the waiter served","note":"考试爱考过去分词作后置定语;口语里常直接用定语从句、甚至省略关系词"},{"exam":"a man eating fish / fish eaten by a man（考试对比)","real":"the guy eating fish over there","note":"真实口语里 -ing 后置定语很自然;-ed 被动定语在书面/正式语体里更常见"}]}'::jsonb, 'sufe');
